import numpy as np
from scipy.signal import butter, sosfiltfilt
from scipy.spatial.distance import pdist, squareform
from colony_lib.datasets import load_dataset
from colony_lib.recurrence import compute_rqa_metrics
ds = load_dataset("neural_eeg"); fs=128.0; data=np.asarray(ds.data)
def band(x,lo,hi):
    return sosfiltfilt(butter(5,[lo/(fs/2),hi/(fs/2)],btype="band",output="sos"), x)
def emb(x,m=3,tau=2):
    idx=np.arange(m)*tau; N=len(x)-(m-1)*tau
    return np.stack([x[i:i+N] for i in idx],axis=1)
for metric in ("chebyshev","euclidean"):
    for name,(lo,hi) in {"Alpha":(8,12),"Gamma":(30,45)}.items():
        e=emb(band(data[:5000,0],lo,hi)); D=squareform(pdist(e,metric=metric))
        iu=np.triu_indices(len(D),1); eps=float(np.quantile(D[iu],0.05))
        m=compute_rqa_metrics(D<=eps)
        print(f"{metric:10s} {name}: RR={m['RR']:.3f} DET={m['DET']:.3f} LAM={m['LAM']:.3f} ENT={m['ENT']:.3f}")
EOF"}

